mapper.select:
SELECT api_name AS apiName,
       COUNT(*) AS executeCount,
       ROUND(AVG(cost_time_ms), 2) AS avgCostTimeMs,
       MAX(cost_time_ms) AS maxCostTimeMs,
       MIN(cost_time_ms) AS minCostTimeMs,
       SUM(CASE WHEN success = 0 THEN 1 ELSE 0 END) AS failedCount
FROM tb_temu_api_log

    cost_time_ms IS NOT NULL
    AND app_id = #{query.appId}
    AND api_name LIKE CONCAT('%', #{query.apiName}, '%')
    AND seller_id = #{query.sellerId}
    AND success = #{query.success}
    AND status_code = #{query.statusCode}
    AND error_code = #{query.errorCode}
    AND cost_time_ms >= #{query.minCostTimeMs}
    AND cost_time_ms <= #{query.maxCostTimeMs}
    AND create_time >= #{query.createTimeStart}
    AND create_time <= #{query.createTimeEnd}

GROUP BY api_name
ORDER BY avgCostTimeMs DESC

mapper.delete:
DELETE FROM tb_temu_api_log
WHERE create_time < #{cutoffTime}
ORDER BY create_time ASC
LIMIT #{limit}
